import{_ as o,o as t,c as a,a2 as s}from"./chunks/framework.a6FUKr6c.js";const u=JSON.parse('{"title":"Database store","description":"","frontmatter":{},"headers":[],"relativePath":"repositories/database.md","filePath":"repositories/database.md","lastUpdated":1795192699000}'),n={name:"repositories/database.md"};function c(d,e,r,i,l,p){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="database-store" tabindex="-1">Database store <a class="header-anchor" href="#database-store" aria-label="Permalink to &quot;Database store&quot;">​</a></h1><p><code>@chamvi/store-db</code> (formerly <code>@chamvi/store-typeorm</code>) keeps everything the engine persists in Postgres through TypeORM. Its repositories pass the port suites of <code>@chamvi/test-kit</code> unchanged, so the engine behaves the same on memory and on Postgres, also with several replicas on one database.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E3E5EA;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/store-db</span><span style="color:#E7C58C;"> typeorm</span><span style="color:#E7C58C;"> pg</span></span></code></pre></div><p><code>typeorm</code> (<code>^1.1.2</code>) and <code>pg</code> (<code>^8</code>) are peer dependencies; the services that use the repositories come from <code>@chamvi/core</code>.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> dataSource = </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> DataSource({</span></span>
<span class="line"><span style="color:#E3E5EA;">    type: </span><span style="color:#E7C58C;">&#39;postgres&#39;</span><span style="color:#E3E5EA;">,</span></span>
<span class="line"><span style="color:#E3E5EA;">    url: process.env.DATABASE_URL,</span></span>
<span class="line"><span style="color:#E3E5EA;">    entities: STORE_ENTITIES,</span></span>
<span class="line"><span style="color:#E3E5EA;">    migrations: STORE_MIGRATIONS,</span></span>
<span class="line"><span style="color:#E3E5EA;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> dataSource.initialize();</span></span>
<span class="line"><span style="color:#8EA7FF;">await</span><span style="color:#E3E5EA;"> migrateStore(dataSource);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> engine = </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> Engine({</span></span>
<span class="line"><span style="color:#80858F;">    // runs, steps, checkpoints, effects, artifacts, state, locks and idempotency keys: services over the database repositories</span></span>
<span class="line"><span style="color:#E3E5EA;">    runService: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> RunService({ repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> DatabaseRunRepository(dataSource), clock: systemClock }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    stepService: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> StepService({ repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> DatabaseStepRepository(dataSource) }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    checkpointService: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> CheckpointService({ repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> DatabaseCheckpointRepository(dataSource) }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    effectService: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> EffectService({ repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> DatabaseEffectRepository(dataSource) }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    agentRevisionService: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> AgentRevisionService({ repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> DatabaseAgentRevisionRepository(dataSource) }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    artifactService: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> ArtifactService({ repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> DatabaseArtifactRepository(dataSource) }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    stateService: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> StateService({</span></span>
<span class="line"><span style="color:#E3E5EA;">        repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> DatabaseStateRepository(dataSource),</span></span>
<span class="line"><span style="color:#E3E5EA;">        documentRepository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> DatabaseStateDocumentRepository(dataSource),</span></span>
<span class="line"><span style="color:#E3E5EA;">    }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    lockService: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> LockService({ repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> DatabaseLockRepository(dataSource), clock: systemClock }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    idempotencyService: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> IdempotencyService({ repository: </span><span style="color:#8EA7FF;">new</span><span style="color:#E3E5EA;"> DatabaseIdempotencyRepository(dataSource), clock: systemClock }),</span></span>
<span class="line"><span style="color:#E3E5EA;">    agents: [triage],</span></span>
<span class="line"><span style="color:#E3E5EA;">});</span></span></code></pre></div><p>Every aggregate is a repository of its own over the same <code>DataSource</code>, the ports&#39; repositories <code>DatabaseRunRepository</code>, <code>DatabaseStepRepository</code>, <code>DatabaseCheckpointRepository</code>, <code>DatabaseEffectRepository</code>, <code>DatabaseArtifactRepository</code>, <code>DatabaseStateRepository</code>, <code>DatabaseStateDocumentRepository</code>, <code>DatabaseIdempotencyRepository</code>, <code>DatabaseLockRepository</code>, <code>DatabaseAgentRevisionRepository</code>, <code>DatabaseConnectionRepository</code> and <code>DatabaseConversationRepository</code> (each <code>new ...(dataSource)</code>, the services of <code>@chamvi/core</code> on them; the connection repository&#39;s <code>entries</code> and <code>secrets</code> share its manager in a transaction, and <code>findFence</code> reads the lease&#39;s lock row <code>FOR SHARE</code>; the conversation repository&#39;s <code>items</code>, <code>notes</code> and <code>operations</code> share its manager too, and its locked read takes <code>FOR NO KEY UPDATE</code>, which does not hold off the rows referencing the conversation). The repositories take an initialized <code>DataSource</code> and never initialize or destroy it. The database must exist; create it beforehand, for example with <code>createDatabase()</code> from <code>typeorm-extension</code>.</p><p>On shutdown, drain the engine before destroying the data source:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#80858F;">// the store never destroys the data source: the app closes it last</span></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> shutdown = </span><span style="color:#8EA7FF;">async</span><span style="color:#E3E5EA;"> () </span><span style="color:#8EA7FF;">=&gt;</span><span style="color:#E3E5EA;"> {</span></span>
<span class="line"><span style="color:#E3E5EA;">    clearInterval(purge);</span></span>
<span class="line"><span style="color:#8EA7FF;">    await</span><span style="color:#E3E5EA;"> engine.drain();</span></span>
<span class="line"><span style="color:#8EA7FF;">    await</span><span style="color:#E3E5EA;"> dataSource.destroy();</span></span>
<span class="line"><span style="color:#E3E5EA;">};</span></span></code></pre></div><p>Each repository takes one argument, an initialized Postgres data source that lists <code>STORE_ENTITIES</code> and <code>STORE_MIGRATIONS</code> (or a manager of it). The repositories take no clock: the services do (<code>RunService</code>, <code>LockService</code>, <code>IdempotencyService</code>, <code>ConnectionService</code> and <code>ConversationService</code> take <code>clock</code>), for claims, keys, locks, fences, retention and <code>updatedAt</code>.</p><h2 id="migrations" tabindex="-1">Migrations <a class="header-anchor" href="#migrations" aria-label="Permalink to &quot;Migrations&quot;">​</a></h2><p><code>migrateStore(dataSource)</code> runs the pending migrations under the Postgres advisory lock <code>chamvi:migrations</code> (<code>MIGRATION_LOCK_NAME</code>). Call it on every boot: replicas that start at once wait for each other, and each migration is applied and recorded once. Each call uses one pooled connection, the one holding the lock, for the migrations as well. chamvi is pre-1.0, so a new version may ship a new migration.</p><p>The baseline <code>1794096000000-uuid-baseline.ts</code> (<code>UuidBaseline1794096000000</code>) creates the whole schema with a uuid v7 <code>id</code> primary key on every table (see <a href="#tables">Tables</a>) and validated foreign keys. It cannot upgrade a database created by an earlier chamvi: <code>migrateStore</code> refuses such a database, before it changes anything, with an error (<code>store_legacy_schema</code>) that names <a href="/guide/upgrading#upgrading-to-0-8">Upgrading</a>. Start on a new, empty database. The migration after it, <code>ConnectionsRevisionsItemBytes1794230765000</code>, changes that schema in place: the connection settings and secrets, <code>chamvi_runs.agent_revision</code> and <code>chamvi_conversation_items.bytes</code> (filled for the stored items under an exclusive lock on that table, see <a href="/guide/upgrading#upgrading-to-0-9">Upgrading</a>). <code>LockTokens1795093873329</code> adds the lock fencing tokens: the table <code>chamvi_lock_tokens</code> and the column <code>chamvi_locks.token</code>, filled for the stored locks (see <a href="/guide/upgrading#upgrading-to-0-10">Upgrading</a>).</p><p><code>pendingMigrations(dataSource)</code> resolves the names of the migrations not run yet, in order, without writing anything (it never creates TypeORM&#39;s <code>migrations</code> table); <code>chamvi start --check</code> uses it to refuse a database a start with <code>CHAMVI_MIGRATE=false</code> could not run on (with the default <code>true</code> a start migrates, so the check passes). <code>chamvi start --check</code> also refuses a database with an earlier schema, whatever <code>CHAMVI_MIGRATE</code> says.</p><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Table</th><th>Holds</th><th>Keys and indexes</th></tr></thead><tbody><tr><td><code>chamvi_runs</code></td><td>Runs; JSON columns for trigger, output, error, usage, subtree usage, wait point and <code>taint</code>; the run&#39;s <code>address</code> in the <code>thread</code> column; claim owner and expiry; the conversation binding; <code>parent_run_id</code></td><td>PK <code>id</code> (uuid v7); <code>(agent, status, concurrency_key)</code>; <code>(status, created_at, id)</code>; <code>conversation_scope_id</code>; <code>parent_run_id</code> (FK to <code>id</code>)</td></tr><tr><td><code>chamvi_steps</code></td><td>Append-only steps</td><td>PK <code>id</code> (bigint); <code>(run_id, step_index)</code></td></tr><tr><td><code>chamvi_checkpoints</code></td><td>The latest checkpoint per run</td><td>PK <code>id</code>; unique <code>run_id</code>; <code>conversation_scope_id</code></td></tr><tr><td><code>chamvi_conversations</code></td><td>Conversation identities, generation, active owner and its snapshot</td><td>PK <code>id</code> (uuid v7); unique <code>key</code> (the identity&#39;s sha256); <code>active_run_id</code></td></tr><tr><td><code>chamvi_conversation_items</code></td><td>Transcript items and the send journal, each with the UTF-8 byte length of its text (<code>bytes</code>), which the recall selects by</td><td>PK <code>id</code> (bigint); unique <code>(scope_id, generation, key)</code>; <code>(scope_id, generation, created_at, id)</code>; <code>run_id</code></td></tr><tr><td><code>chamvi_conversation_notes</code></td><td>Explicit notes</td><td>PK <code>id</code>; unique <code>(scope_id, generation, key)</code>; <code>expires_at</code>; <code>run_id</code></td></tr><tr><td><code>chamvi_conversation_operations</code></td><td>Note operation receipts</td><td>PK <code>id</code>; unique <code>(scope_id, generation, operation_id)</code>; <code>(scope_id, created_at, operation_id)</code>; <code>run_id</code></td></tr><tr><td><code>chamvi_idempotency_keys</code></td><td>Intake keys</td><td>PK <code>id</code>; unique <code>(scope, key)</code>; <code>expires_at</code></td></tr><tr><td><code>chamvi_locks</code></td><td>Keyed leases</td><td>PK <code>id</code>; unique <code>key</code>; <code>expires_at</code>; <code>token</code> (bigint)</td></tr><tr><td><code>chamvi_lock_tokens</code></td><td>The last fencing token issued</td><td>PK <code>id</code> (the one row <code>1</code>); <code>value</code> (bigint)</td></tr><tr><td><code>chamvi_effects</code></td><td>Recorded effect results</td><td>PK <code>id</code>; unique <code>key</code></td></tr><tr><td><code>chamvi_kv</code></td><td>Agent key-value state</td><td>PK <code>id</code>; unique <code>(agent, key)</code>, <code>key</code> <code>COLLATE &quot;C&quot;</code></td></tr><tr><td><code>chamvi_docs</code></td><td>Agent document collections</td><td>PK <code>id</code>; unique <code>(agent, collection, document_id)</code>; GIN index on <code>doc</code></td></tr><tr><td><code>chamvi_artifacts</code></td><td>Artifact metadata and bytes (<code>data</code> <code>bytea</code>)</td><td>PK <code>id</code> (uuid v7); unique <code>(run_id, key)</code> (the private write key); <code>run_id</code>, with no foreign key because attachments are stored before their run</td></tr><tr><td><code>chamvi_agent_revisions</code></td><td>One revision marker per folder agent: <code>hash</code> varchar(128), <code>changed_at</code></td><td>PK <code>id</code>; unique <code>agent</code> varchar(64) <code>COLLATE &quot;C&quot;</code></td></tr><tr><td><code>chamvi_connections</code>, <code>chamvi_connection_entries</code></td><td>Sealed connection entries and the key that wraps them</td><td>PK <code>id</code>; unique <code>name</code>, unique <code>(connection_id, key)</code> (foreign key <code>ON DELETE CASCADE</code>)</td></tr></tbody></table><p>Every table has a single <code>id</code> primary key, uuid v7 except the bigint <code>id</code> of the append-only steps and conversation items. What identifies a row to the store is the unique key listed, and an upsert overwrites its other columns but keeps the stored <code>id</code>. A value that is not a UUID is simply not found by <code>findOne</code>, <code>read</code> or <code>find({ ids })</code> (and a step, checkpoint or conversation turn of such a run id fails with <code>RunNotFoundError</code>), never a Postgres error.</p><p>Conversation rows, active owners, transcript items, notes and operation receipts use foreign keys to their local runs and identities. Steps and checkpoints also require an existing run. Use the same DataSource for every built-in TypeORM role; these relationships do not create a transaction spanning run dispatch, conversation mutation and generic effects. See <a href="/guide/conversations">Conversation memory</a>.</p><h2 id="how-it-keeps-the-contract" tabindex="-1">How it keeps the contract <a class="header-anchor" href="#how-it-keeps-the-contract" aria-label="Permalink to &quot;How it keeps the contract&quot;">​</a></h2><ul><li><strong>Repositories and query builders.</strong> Every method goes through the entities&#39; TypeORM repositories, find options and query builders. Hand-written fragments remain only where find options cannot express the condition: the <code>jsonb_exists</code> key check and the top-level <code>doc -&gt; key</code> equality of <code>DatabaseStateDocumentRepository.findContaining</code> (TypeORM has neither operator) and the wait point kind of <code>DatabaseRunRepository.findByWaitKind</code> (<code>waiting-&gt;&gt;&#39;kind&#39;</code>, rapiq&#39;s TypeORM adapter has no jsonb path).</li><li><strong>Runs and steps in transactions.</strong> <code>DatabaseRunRepository</code> and <code>DatabaseStepRepository</code> implement the ports of <code>@chamvi/store</code> on <code>EntityRepositoryAdapter</code>; <code>RunService</code> reads a run <code>FOR NO KEY UPDATE</code> in a transaction, decides, then writes the changed columns (the lock never blocks the <code>KEY SHARE</code> locks of a step, checkpoint or child run insert). A taken id is <code>EntityConflictError</code> (<code>create</code> resolves <code>false</code>), a missing parent <code>EntityRelationError</code> (<code>RunNotFoundError</code>).</li><li><strong>Locks and idempotency keys in transactions.</strong> <code>LockService.acquire</code> and <code>IdempotencyService.claim</code> first read the row once without a lock: a held lease or an unexpired key is refused on that one statement. A row that read found expired is taken over in a transaction that reads it <code>FOR UPDATE</code>, reads the clock and takes the row over only when it is still expired. A key that read found free (or one gone by the locked read) is inserted in a transaction of its own; a unique violation (<code>EntityConflictError</code>, the key was taken meanwhile) is followed by the same locked takeover in a new transaction. A renewal and a release read the lock row <code>FOR UPDATE</code> too, so a reader that locks the row sees a lease before or after a change, never one in flight. An insert and a takeover first take a fencing token: one <code>UPDATE chamvi_lock_tokens SET value = GREATEST(value + 1, &lt;now in µs&gt;) ... RETURNING value</code> in the same transaction, so concurrent acquirers serialize on that row and no token repeats.</li><li><strong>One statement for each listed atomic operation</strong>, never read-then-write in JavaScript: <ul><li>Effects, state keys, state documents and agent revision markers: an upsert on the natural key (<code>key</code>, <code>(agent, key)</code>, <code>(agent, collection, document_id)</code>, <code>agent</code>) that keeps the stored <code>id</code> and returns it. A marker needs no atomic compare: the engine reads and writes it under the store lock <code>agents:&lt;name&gt;</code>.</li></ul></li><li><strong>Checkpoints and keyed artifacts in a transaction.</strong> <code>CheckpointService.save</code> reads the run&#39;s checkpoint row <code>FOR UPDATE</code>, keeps the higher step index and writes; <code>ArtifactService.save</code> reads the <code>(run_id, key)</code> row the same way and keeps its <code>id</code>, <code>agent</code> and <code>created_at</code>. Two first writes that both found no row insert, the loser&#39;s unique violation (<code>EntityConflictError</code>) is retried once in a new transaction, which finds the row. <code>ArtifactService.create</code> inserts; a taken <code>id</code> or <code>(run_id, key)</code> is <code>EntityConflictError</code> and resolves <code>false</code>.</li><li><strong>Conversation transactions.</strong> Conversation ownership and journal changes use transactions and a <code>FOR NO KEY UPDATE</code> lock on the conversation row rather than the single-statement pattern above (the row is never deleted and its key never changes, so the lock does not block the <code>KEY SHARE</code> locks of child-row foreign key checks).</li><li><strong>Missing runs.</strong> A step, checkpoint or conversation turn of a run that does not exist fails the foreign key; the services report it as <code>RunNotFoundError</code>, like on memory.</li><li><strong>Time from the clock.</strong> The services read their <code>IClock</code> and hand the repository the finished values; queries never call the database&#39;s <code>now()</code>.</li><li><strong>No aliasing.</strong> Values are serialized into the query and parsed out again; nothing is cached in memory.</li><li><strong>Dates.</strong> Timestamps are <code>timestamptz</code>; <code>trigger.receivedAt</code>, <code>trigger.attachments[].createdAt</code>, <code>waiting.expiresAt</code>, <code>waiting.notifiedAt</code> and <code>taint.at</code> live in JSON and are revived as <code>Date</code>.</li></ul><h2 id="housekeeping" tabindex="-1">Housekeeping <a class="header-anchor" href="#housekeeping" aria-label="Permalink to &quot;Housekeeping&quot;">​</a></h2><p>Expired idempotency keys and locks never block anyone, but they stay in their tables until purged:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#80858F;">// expired keys and locks stay until purged: purge every hour</span></span>
<span class="line"><span style="color:#8EA7FF;">const</span><span style="color:#E3E5EA;"> purge = setInterval(() </span><span style="color:#8EA7FF;">=&gt;</span><span style="color:#E3E5EA;"> {</span></span>
<span class="line"><span style="color:#E3E5EA;">    Promise.all([engine.idempotencyService.purgeExpired(), engine.lockService.purgeExpired()])</span></span>
<span class="line"><span style="color:#E3E5EA;">        .catch((e: unknown) </span><span style="color:#8EA7FF;">=&gt;</span><span style="color:#E3E5EA;"> console.error(e));</span></span>
<span class="line"><span style="color:#E3E5EA;">}, </span><span style="color:#E7C58C;">60</span><span style="color:#E3E5EA;"> * </span><span style="color:#E7C58C;">60</span><span style="color:#E3E5EA;"> * </span><span style="color:#E7C58C;">1000</span><span style="color:#E3E5EA;">);</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E3E5EA;">purge.unref();</span></span></code></pre></div><p><code>engine.idempotencyService.purgeExpired(now?)</code> and <code>engine.lockService.purgeExpired(now?)</code> each delete their expired rows (one <code>DELETE ... WHERE expires_at &lt;= now</code>, through <code>removeExpiredBy</code>) and return the number removed. The default time comes from the clock. Effects have no expiry and are never purged. Direct engine users schedule both as above; the app&#39;s built-in store module schedules them with <code>CHAMVI_PURGE_INTERVAL_MS</code>.</p><h2 id="differences-from-memory-repositories" tabindex="-1">Differences from memory repositories <a class="header-anchor" href="#differences-from-memory-repositories" aria-label="Permalink to &quot;Differences from memory repositories&quot;">​</a></h2><ul><li><strong>Opaque values are JSON.</strong> A run&#39;s <code>output</code>, step <code>input</code>/<code>output</code>/<code>error</code>, checkpoint messages, effect results and state lose <code>Date</code>, <code>undefined</code> and <code>Map</code> fidelity, and a typed array such as <code>Uint8Array</code> comes back as an object keyed by index. A <code>BigInt</code> or a circular structure makes the write throw a <code>TypeError</code>.</li><li><strong>NUL characters and lone surrogates become U+FFFD</strong> in opaque values, keys and strings alike, because <code>jsonb</code> cannot hold them.</li><li><strong>Artifact bytes are <code>bytea</code></strong>, never selected by <code>findOne</code> or <code>find</code>, and come back from <code>readData</code> (<code>ArtifactService.read</code>) as a plain <code>Uint8Array</code>. Postgres caps a <code>bytea</code> value at 1 GB and the whole value travels in one query, so keep artifacts small enough for memory. Nothing purges artifacts yet.</li><li><strong>Identifiers have length limits</strong> (the memory repositories have none): <code>concurrencyKey</code>, <code>address</code>, claim owners, step names, document collections and document ids 255; idempotency, lock, effect and state keys 512; idempotency scopes 1024 (<code>&lt;agent&gt;:&lt;source&gt;:&lt;kind&gt;:&lt;id&gt;</code> with the invoker URI-encoded, leaving about 950 characters for the encoded <code>kind</code> and <code>id</code>). A longer value makes the write fail with the driver&#39;s <code>value too long</code> error, so validate user-supplied keys before they reach <code>dispatch</code> (a rejected run with an <code>idempotencyKey</code> keeps its key reserved until the key expires).</li><li><strong><code>null</code> in an optional property reads back as absent:</strong> a run <code>output</code> of <code>null</code>, and a step <code>input</code>, <code>output</code> or <code>error</code> of <code>null</code>, are stored as SQL <code>NULL</code>. <code>effectService.save(key, undefined)</code> and <code>upsertDocument(..., undefined)</code> store <code>null</code> on every store.</li><li><strong><code>findDocuments</code> <code>where</code> matches by top-level equality, as on memory:</strong> <code>jsonb</code> containment (<code>@&gt;</code>, which the GIN index serves) narrows the rows and <code>doc -&gt; key = value</code> keeps exact matches only, so a nested object or array matches an equal one, not a superset. A key whose value is <code>undefined</code> matches object documents that lack the key. Documents come back ordered by <code>document_id</code> (code point) on both stores.</li><li><strong><code>runs.find</code> ties</strong> on <code>createdAt</code> are broken by <code>id</code> (uuid order, reversed for <code>order: &#39;desc&#39;</code>); time-ordered ids make that the creation order, as on memory.</li></ul>`,26)])])}const y=o(n,[["render",c]]);export{u as __pageData,y as default};
